enrollments.service.ts and its unit test:

@Injectable()
export class EnrollmentsService {
  private readonly repo = new EnrollmentsRepository(new PrismaService());

  enroll(userId: string, courseId: string) {
    return this.repo.create({ userId, courseId });
  }
}

// enrollments.service.spec.ts
const fakeRepo = { create: jest.fn().mockResolvedValue({ userId: 'u1', courseId: 'c1' }) };
const moduleRef = await Test.createTestingModule({
  providers: [EnrollmentsService, { provide: EnrollmentsRepository, useValue: fakeRepo }],
}).compile();
await moduleRef.get(EnrollmentsService).enroll('u1', 'c1');

Statement: "In this test, enroll() calls fakeRepo.create, so the test runs without a database."

